import ee, math, datetime
ee.Initialize(project='earthsense-436113')

def to_db(img):
    return ee.Image(10).multiply(img.select('VV').log10()).rename('VV_dB')

def date_window(center_str, days):
    d = datetime.datetime.strptime(center_str, '%Y-%m-%d')
    start = (d - datetime.timedelta(days=days)).strftime('%Y-%m-%d')
    end = (d + datetime.timedelta(days=days + 1)).strftime('%Y-%m-%d')  # inclusive end
    return start, end

def is_number(x):
    try:
        return (x is not None) and (not isinstance(x, bool)) and math.isfinite(float(x))
    except Exception:
        return False

# 1. Geometry: shared border buffer (1 km)
try:
    counties = ee.FeatureCollection('TIGER/2018/Counties').filter(ee.Filter.eq('STATEFP', '05'))
    craig = counties.filter(ee.Filter.eq('NAME', 'Craighead')).first()
    jack = counties.filter(ee.Filter.eq('NAME', 'Jackson')).first()
    craig_geom = ee.Feature(craig).geometry()
    jack_geom = ee.Feature(jack).geometry()
    border_line = craig_geom.boundary().intersection(jack_geom.boundary(), ee.ErrorMargin(10))
    aoi = border_line.buffer(1000).intersection(craig_geom.union(jack_geom), ee.ErrorMargin(10))
    # Basic AOI checks
    if aoi.isEmpty().getInfo():
        print("AOI empty after border buffer.")
        print("C3")
        raise SystemExit
    aoi_area_km2 = ee.Number(aoi.area(maxError=1)).divide(1e6).getInfo()
    border_km = ee.Number(border_line.length(maxError=1)).divide(1000).getInfo()
    print(f"AOI km2: {aoi_area_km2:.2f}, Border length km: {border_km:.2f}, Buffer m: 1000")
except Exception as e:
    print("Geometry construction failed.")
    print("D")
    raise SystemExit

def s1_water_stats(date_str):
    # Try ±6 days then ±10
    for win in [6, 10]:
        start, end = date_window(date_str, win)
        col = (ee.ImageCollection('COPERNICUS/S1_GRD')
               .filterBounds(aoi)
               .filterDate(start, end)
               .filter(ee.Filter.eq('instrumentMode', 'IW'))
               .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
               .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING')).merge(
                    ee.ImageCollection('COPERNICUS/S1_GRD')
                    .filterBounds(aoi)
                    .filterDate(start, end)
                    .filter(ee.Filter.eq('instrumentMode', 'IW'))
                    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
                    .filter(ee.Filter.eq('orbitProperties_pass', 'ASCENDING'))
               ))
        size = col.size().getInfo()
        if size == 0:
            if win == 10:
                return None, {'sensor': 'S1', 'size': 0, 'window': win}
            continue
        med = col.median()
        vv_db = to_db(med)
        valid_count = vv_db.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=aoi,
            scale=1000,
            maxPixels=1e9
        ).get('VV_dB').getInfo()
        if (valid_count is None) or (valid_count == 0):
            return 'C2', {'sensor': 'S1', 'size': size, 'window': win, 'valid_px': 0}
        water = vv_db.lt(-17)
        water_area_m2 = water.updateMask(water).multiply(ee.Image.pixelArea()).reduceRegion(
            reducer=ee.Reducer.sum(),
            geometry=aoi,
            scale=1000,
            maxPixels=1e9
        ).get('VV_dB').getInfo()
        water_km2 = None if water_area_m2 is None else (water_area_m2 / 1e6)
        if not is_number(water_km2) or water_km2 < 0 or water_km2 > aoi_area_km2 * 1.5:
            return 'C3', {'sensor': 'S1', 'size': size, 'window': win}
        return water_km2, {'sensor': 'S1', 'size': size, 'window': win, 'valid_px': int(valid_count)}
    return None, {'sensor': 'S1', 'size': 0}

def s2_water_stats(date_str):
    # Try ±6 then ±10
    def mask_s2(img):
        qa = img.select('QA60')
        cloud = qa.bitwiseAnd(1 << 10).Or(qa.bitwiseAnd(1 << 11))
        return img.updateMask(cloud.Not())
    for win in [6, 10]:
        start, end = date_window(date_str, win)
        col = (ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
               .filterBounds(aoi)
               .filterDate(start, end)
               .filter(ee.Filter.lte('CLOUDY_PIXEL_PERCENTAGE', 80)))
        size = col.size().getInfo()
        if size == 0:
            if win == 10:
                return None, {'sensor': 'S2', 'size': 0, 'window': win}
            continue
        mcol = col.map(mask_s2)
        med = mcol.median()
        # Valid pixel count after mask
        valid_count = med.select('B3').reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=aoi,
            scale=1000,
            maxPixels=1e9
        ).get('B3').getInfo()
        if (valid_count is None) or (valid_count == 0):
            return 'C2', {'sensor': 'S2', 'size': size, 'window': win, 'valid_px': 0}
        # Total pixels at 1 km for "cloud %" estimate
        total_count = ee.Image.constant(1).rename('one').reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=aoi,
            scale=1000,
            maxPixels=1e9
        ).get('one').getInfo()
        valid_pct = 100.0 * (valid_count / max(1, total_count))
        # MNDWI
        mndwi = med.normalizedDifference(['B3', 'B11']).rename('MNDWI')
        water = mndwi.gt(0.3)
        water_area_m2 = water.updateMask(water).multiply(ee.Image.pixelArea()).reduceRegion(
            reducer=ee.Reducer.sum(),
            geometry=aoi,
            scale=1000,
            maxPixels=1e9
        ).get('MNDWI').getInfo()
        water_km2 = None if water_area_m2 is None else (water_area_m2 / 1e6)
        if not is_number(water_km2) or water_km2 < 0 or water_km2 > aoi_area_km2 * 1.5:
            return 'C3', {'sensor': 'S2', 'size': size, 'window': win}
        return water_km2, {'sensor': 'S2', 'size': size, 'window': win, 'valid_px': int(valid_count), 'valid_pct': valid_pct}
    return None, {'sensor': 'S2', 'size': 0}

def get_water(date_str):
    # Try S1 first, then S2
    w, meta = s1_water_stats(date_str)
    if w == 'C2':
        return None, meta, 'C2'
    if w == 'C3':
        return None, meta, 'C3'
    if w is None:
        # fallback to S2
        w2, meta2 = s2_water_stats(date_str)
        if w2 == 'C2':
            return None, meta2, 'C2'
        if w2 == 'C3':
            return None, meta2, 'C3'
        if w2 is None:
            return None, meta2, 'C1'
        return w2, meta2, None
    return w, meta, None

try:
    d2023 = '2023-04-13'
    d2025 = '2025-04-13'

    w23, m23, e23 = get_water(d2023)
    if e23 == 'C1':
        print(f"2023 Images: 0")
        print("C1")
        raise SystemExit
    if e23 == 'C2':
        print(f"2023 Images: {m23.get('size', 'NA')} (No valid pixels)")
        print("C2")
        raise SystemExit
    if e23 == 'C3':
        print(f"2023 Processing failure.")
        print("C3")
        raise SystemExit

    w25, m25, e25 = get_water(d2025)
    if e25 == 'C1':
        print(f"2025 Images: 0")
        print("C1")
        raise SystemExit
    if e25 == 'C2':
        print(f"2025 Images: {m25.get('size', 'NA')} (No valid pixels)")
        print("C2")
        raise SystemExit
    if e25 == 'C3':
        print(f"2025 Processing failure.")
        print("C3")
        raise SystemExit

    # Print concise stats
    def fmt_meta(label, w, meta):
        base = f"{label} {meta['sensor']} imgs: {meta.get('size','?')} (±{meta.get('window','?')}d)"
        if meta['sensor'] == 'S2':
            vp = meta.get('valid_pct', None)
            if vp is not None:
                base += f", valid%: {vp:.1f}"
        base += f"; water km2: {w:.3f}; valid px: {meta.get('valid_px','?')}"
        print(base)

    fmt_meta("2023", w23, m23)
    fmt_meta("2025", w25, m25)

    if not is_number(w23) or not is_number(w25):
        print("C3")
    else:
        if w25 > w23:
            print("A")
        else:
            print("B")
except Exception as e:
    print("D")

